// Entry of `dist/askfolio-markdown.js` (D22, task 44): the widget's Markdown renderer for a page
// built on the headless client, without the widget's Copy button. `markdown.ts` is unchanged: this
// entry only gives it a document and no Copy button. Its declarations are what
// `dist/askfolio-markdown.d.ts` ships; they import nothing (scripts/build-types.mjs checks it).
//
// It imports `markdown.ts`, which bundles `marked`'s lexer; it is not a client module (the client
// file stays free of the parser), and touches no DOM at import time.
import { renderMarkdown as render } from "./markdown.js";

/** Options of `renderMarkdown`. */
export interface RenderMarkdownOptions {
  /** The document that creates the nodes. Defaults to the global `document`; required outside a browser. */
  document?: Document;
}

/**
 * Renders an answer's Markdown into a fragment of allowlisted elements and text nodes, the
 * widget's renderer (docs/08 §9): no raw HTML, no images, no attributes but `href` on http(s)
 * links (opened in a new tab, `rel="noopener noreferrer nofollow"`) and `start` on ordered
 * lists; `h1` and `h2` become `h3`. An answer past the parser's bounds, or one it fails on, is
 * rendered as plain paragraphs. Insert the fragment with `replaceChildren` or `append`; a
 * framework needs a ref. Never throws, except with no `document` to build nodes with.
 * While text streams, re-render at most once per animation frame.
 */
export function renderMarkdown(
  markdown: string,
  options?: RenderMarkdownOptions,
): DocumentFragment {
  const doc = options?.document ?? (typeof document === "undefined" ? undefined : document);
  if (doc === undefined) {
    throw new TypeError("renderMarkdown needs a document: pass { document } outside a browser");
  }
  return render(doc, typeof markdown === "string" ? markdown : "", { copyButton: null });
}
