// Markdown rendering and sanitisation (docs/08-widget.md §9, docs/06-security-and-abuse.md T11).
// The widget is the boundary for script injection into the host page.
//
// `marked` parses the answer into tokens; HTML is never parsed: `html` tokens are rendered as
// text. The sanitiser is the token renderer below, an allowlist by construction: it creates only
// the elements of `docs/08` §9 with `createElement`, sets text with `createTextNode`, and sets two
// attributes: `href` on links whose URL parses with protocol `http:` or `https:` and carries no
// credentials (kept links get `target="_blank"` and `rel="noopener noreferrer nofollow"`), and the
// numeric `start` of an ordered list. No string ever reaches `innerHTML`. `h1` and `h2` become
// `h3`, images become their alt text, other links their text (docs/08 §9 Decision, S84 (a)).
//
// The parser is recursive and some inputs are quadratic for it: an answer past the bounds of
// `lexable` (S84 (j)), or one the parser fails on, is shown as plain text.
import {
  WIDGET_MARKDOWN_MAX_CHARS,
  WIDGET_MARKDOWN_MAX_DELIMITERS,
  WIDGET_MARKDOWN_MAX_LINE_DEPTH,
  WIDGET_MARKDOWN_MAX_RUN,
  WIDGET_STREAM_RENDER_INTERVAL_MS,
} from "@askfolio/shared";
import { Lexer, type Token, type Tokens } from "marked";

export type RenderOptions = {
  /** Code blocks get a Copy button (answers with `validation: "not_required"`). */
  copyButton: { label: string } | null;
};

const ENTITY = /&(?:#(\d{1,7})|#[xX]([0-9a-fA-F]{1,6})|([a-zA-Z]{2,8}));/g;
/** The named references an answer plausibly holds; others stay as written. */
const NAMED: Readonly<Record<string, string>> = {
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  apos: "'",
  nbsp: " ",
  copy: "©",
  reg: "®",
  trade: "™",
  hellip: "…",
  mdash: "—",
  ndash: "–",
  lsquo: "‘",
  rsquo: "’",
  ldquo: "“",
  rdquo: "”",
  laquo: "«",
  raquo: "»",
  euro: "€",
  times: "×",
  divide: "÷",
  deg: "°",
  middot: "·",
  bull: "•",
  rarr: "→",
  larr: "←",
};
/** HTML's replacements of numeric references to C1 controls (Windows-1252), 0x80 to 0x9F. */
const C1 = "€\u0081‚ƒ„…†‡ˆ‰Š‹Œ\u008dŽ\u008f" + "\u0090‘’“”•–—˜™š›œ\u009džŸ";

/** The character of a numeric reference, as the HTML parser decodes it. */
function fromCode(code: number): string {
  if (code === 0 || code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) return "�";
  if (code >= 0x80 && code <= 0x9f) return C1[code - 0x80] ?? "�";
  return String.fromCodePoint(code);
}

/** Decodes numeric references and the common named ones in markdown text. */
export function decodeEntities(text: string): string {
  if (!text.includes("&")) return text;
  return text.replace(ENTITY, (match, dec?: string, hex?: string, name?: string) => {
    if (name !== undefined) return NAMED[name] ?? match;
    return fromCode(dec !== undefined ? Number(dec) : Number.parseInt(hex ?? "", 16));
  });
}

/**
 * The `href` to keep, or `null`: only absolute `http:` and `https:` URLs without credentials
 * (`https://trusted.test@evil.test` would show one host and open another) and without
 * backslashes (which URL parsers read as slashes).
 */
export function safeHref(href: string): string | null {
  if (href.includes("\\")) return null;
  try {
    const url = new URL(href);
    if (url.protocol !== "http:" && url.protocol !== "https:") return null;
    return url.username === "" && url.password === "" ? url.href : null;
  } catch {
    return null;
  }
}

// Character codes read by `lexable`.
const TAB = 9;
const NEWLINE = 10;
const SPACE = 32;
const STAR = 42;
const PLUS = 43;
const DASH = 45;
const LESS = 60;
const GREATER = 62;
const OPEN_BRACKET = 91;
const CLOSE_BRACKET = 93;
const UNDERSCORE = 95;
const BACKTICK = 96;
const TILDE = 126;

function isDelimiter(c: number): boolean {
  return (
    c === STAR ||
    c === UNDERSCORE ||
    c === OPEN_BRACKET ||
    c === CLOSE_BRACKET ||
    c === BACKTICK ||
    c === TILDE ||
    c === LESS
  );
}

/**
 * Whether `markdown` stays within the bounds the parser handles quickly and without deep
 * recursion: its length, the longest run of one marker character, the inline delimiters outside
 * fenced code, and the nesting markers at the start of each line. One linear pass.
 */
export function lexable(markdown: string): boolean {
  if (markdown.length > WIDGET_MARKDOWN_MAX_CHARS) return false;
  let previous = -1;
  let run = 0;
  let delimiters = 0;
  let depth = 0;
  let lineStart = true;
  let fenced = false;
  for (let i = 0; i < markdown.length; i += 1) {
    const c = markdown.charCodeAt(i);
    if (c === NEWLINE) {
      lineStart = true;
      depth = 0;
      previous = c;
      run = 0;
      continue;
    }
    if (lineStart && (c === BACKTICK || c === TILDE)) {
      const next = markdown.charCodeAt(i + 1);
      if (next === c && markdown.charCodeAt(i + 2) === c) fenced = !fenced;
    }
    if (c === GREATER || isDelimiter(c)) {
      run = c === previous ? run + 1 : 1;
      if (run > WIDGET_MARKDOWN_MAX_RUN) return false;
    } else {
      run = 0;
    }
    if (!fenced && isDelimiter(c)) {
      delimiters += 1;
      if (delimiters > WIDGET_MARKDOWN_MAX_DELIMITERS) return false;
    }
    if (lineStart && !fenced) {
      const next = markdown.charCodeAt(i + 1);
      const listMarker =
        (c === DASH || c === STAR || c === PLUS) && (next === SPACE || next === TAB);
      if (c === GREATER || listMarker) {
        depth += 1;
        if (depth > WIDGET_MARKDOWN_MAX_LINE_DEPTH) return false;
      } else if (c !== SPACE && c !== TAB) {
        lineStart = false;
      }
    }
    previous = c;
  }
  return true;
}

type Context = { doc: Document; options: RenderOptions };

function element<K extends keyof HTMLElementTagNameMap>(
  ctx: Context,
  parent: Node,
  tag: K,
): HTMLElementTagNameMap[K] {
  const node = ctx.doc.createElement(tag);
  parent.appendChild(node);
  return node;
}

function text(ctx: Context, parent: Node, value: string): void {
  if (value !== "") parent.appendChild(ctx.doc.createTextNode(value));
}

function inline(ctx: Context, parent: Node, tokens: readonly Token[] | undefined): void {
  for (const token of tokens ?? []) {
    switch (token.type) {
      case "strong":
      case "em":
      case "del":
        inline(ctx, element(ctx, parent, token.type), (token as Tokens.Generic).tokens);
        break;
      case "codespan":
        text(ctx, element(ctx, parent, "code"), (token as Tokens.Codespan).text);
        break;
      case "br":
        element(ctx, parent, "br");
        break;
      case "link": {
        const link = token as Tokens.Link;
        const href = safeHref(link.href);
        if (href === null) {
          inline(ctx, parent, link.tokens);
        } else {
          const a = element(ctx, parent, "a");
          a.href = href;
          a.target = "_blank";
          a.rel = "noopener noreferrer nofollow";
          inline(ctx, a, link.tokens);
        }
        break;
      }
      case "image":
        text(ctx, parent, decodeEntities((token as Tokens.Image).text));
        break;
      case "html":
        text(ctx, parent, (token as Tokens.HTML).text);
        break;
      case "checkbox":
        text(ctx, parent, (token as Tokens.Checkbox).checked ? "[x] " : "[ ] ");
        break;
      case "text": {
        const tokenText = token as Tokens.Text;
        if (tokenText.tokens !== undefined && tokenText.tokens.length > 0) {
          inline(ctx, parent, tokenText.tokens);
        } else {
          text(ctx, parent, decodeEntities(tokenText.text));
        }
        break;
      }
      default: {
        // `escape` and any token kind this renderer does not know: its text, never markup.
        const generic = token as Tokens.Generic;
        if (generic.tokens !== undefined) inline(ctx, parent, generic.tokens);
        else if (typeof generic.text === "string") text(ctx, parent, decodeEntities(generic.text));
      }
    }
  }
}

function codeBlock(ctx: Context, parent: Node, code: string): void {
  const copy = ctx.options.copyButton;
  if (copy === null) {
    text(ctx, element(ctx, element(ctx, parent, "pre"), "code"), code);
  } else {
    // Widget chrome around the content: the wrapper and the button are not from the answer.
    const wrapper = element(ctx, parent, "div");
    wrapper.className = "code";
    text(ctx, element(ctx, element(ctx, wrapper, "pre"), "code"), code);
    const button = element(ctx, wrapper, "button");
    button.type = "button";
    button.className = "copy";
    button.textContent = copy.label;
    button.addEventListener("click", () => {
      navigator.clipboard?.writeText(code).catch(() => undefined);
    });
  }
}

function blocks(ctx: Context, parent: Node, tokens: readonly Token[]): void {
  for (const token of tokens) {
    switch (token.type) {
      case "space":
      case "def":
        break;
      case "heading": {
        const depth = Math.min(6, Math.max(3, (token as Tokens.Heading).depth));
        const tag = `h${depth}` as "h3" | "h4" | "h5" | "h6";
        inline(ctx, element(ctx, parent, tag), (token as Tokens.Heading).tokens);
        break;
      }
      case "paragraph":
        inline(ctx, element(ctx, parent, "p"), (token as Tokens.Paragraph).tokens);
        break;
      case "code":
        codeBlock(ctx, parent, (token as Tokens.Code).text);
        break;
      case "blockquote":
        blocks(ctx, element(ctx, parent, "blockquote"), (token as Tokens.Blockquote).tokens);
        break;
      case "list": {
        const list = token as Tokens.List;
        const node = element(ctx, parent, list.ordered ? "ol" : "ul");
        // The numeric start of an ordered list, the only attribute besides a link's href.
        if (list.ordered && typeof list.start === "number" && list.start !== 1) {
          (node as HTMLOListElement).start = list.start;
        }
        for (const item of list.items) blocks(ctx, element(ctx, node, "li"), item.tokens);
        break;
      }
      case "table": {
        const table = token as Tokens.Table;
        const node = element(ctx, parent, "table");
        const headRow = element(ctx, element(ctx, node, "thead"), "tr");
        for (const cell of table.header) inline(ctx, element(ctx, headRow, "th"), cell.tokens);
        const body = element(ctx, node, "tbody");
        for (const row of table.rows) {
          const tr = element(ctx, body, "tr");
          for (const cell of row) inline(ctx, element(ctx, tr, "td"), cell.tokens);
        }
        break;
      }
      case "hr":
        element(ctx, parent, "hr");
        break;
      case "html":
        text(ctx, element(ctx, parent, "p"), (token as Tokens.HTML).text);
        break;
      default:
        // Block-level `text` (tight list items), `checkbox`, and unknown kinds: inline content.
        inline(ctx, parent, [token]);
    }
  }
}

/** `markdown` as plain text: one paragraph, lines separated by `br`. */
function plain(doc: Document, markdown: string): DocumentFragment {
  const fragment = doc.createDocumentFragment();
  const paragraph = doc.createElement("p");
  markdown.split("\n").forEach((line, index) => {
    if (index > 0) paragraph.appendChild(doc.createElement("br"));
    if (line !== "") paragraph.appendChild(doc.createTextNode(line));
  });
  fragment.appendChild(paragraph);
  return fragment;
}

/**
 * Renders `markdown` into a fragment of allowlisted elements and text nodes; plain text when the
 * answer is past the parser bounds or the parser fails. Never throws.
 */
export function renderMarkdown(
  doc: Document,
  markdown: string,
  options: RenderOptions,
): DocumentFragment {
  if (!lexable(markdown)) return plain(doc, markdown);
  try {
    const fragment = doc.createDocumentFragment();
    const tokens = Lexer.lex(markdown, { gfm: true, breaks: false });
    blocks({ doc, options }, fragment, tokens);
    return fragment;
  } catch {
    return plain(doc, markdown);
  }
}

/**
 * Re-renders while text streams in (docs/08 §9): at most once per animation frame and once per
 * `WIDGET_STREAM_RENDER_INTERVAL_MS`, so a long answer is not parsed again on every delta;
 * `flush` renders at once. A failing render is dropped: nothing throws into the host page.
 */
export class FrameRenderer {
  #timer: ReturnType<typeof setTimeout> | null = null;
  #frame: number | null = null;
  #pending: (() => void) | null = null;
  #last = Number.NEGATIVE_INFINITY;

  schedule(render: () => void): void {
    this.#pending = render;
    if (this.#timer !== null || this.#frame !== null) return;
    const wait = Math.max(0, this.#last + WIDGET_STREAM_RENDER_INTERVAL_MS - Date.now());
    this.#timer = setTimeout(() => {
      this.#timer = null;
      this.#frame = requestAnimationFrame(() => {
        this.#frame = null;
        const pending = this.#pending;
        this.#pending = null;
        this.#last = Date.now();
        try {
          pending?.();
        } catch {
          // Never into the host page; the next render or `flush` replaces the content.
        }
      });
    }, wait);
  }

  flush(render: () => void): void {
    this.cancel();
    this.#last = Date.now();
    render();
  }

  cancel(): void {
    if (this.#timer !== null) clearTimeout(this.#timer);
    if (this.#frame !== null) cancelAnimationFrame(this.#frame);
    this.#timer = null;
    this.#frame = null;
    this.#pending = null;
  }
}
